using System.Text.Json;
using System.Text.RegularExpressions;

namespace SignalScheduler.Shared;

/// <summary>
/// The installed build-info.json, generated by the verified Windows pipeline,
/// is the single source of truth for UI2 installed version text. Never show
/// a hard-coded version from the XAML or from a compiled fallback constant.
/// </summary>
public sealed record InstalledBuildInfo(string Version,int Build)
{
    private static readonly Regex Ui2VersionPattern=new(
        @"^8\.0\.0-ui2\.[0-9]+$",
        RegexOptions.Compiled|RegexOptions.CultureInvariant);

    public static InstalledBuildInfo? Parse(string? json)
    {
        if(string.IsNullOrWhiteSpace(json)||json.Length>16_384)return null;
        try
        {
            using var document=JsonDocument.Parse(json);
            var root=document.RootElement;
            if(root.ValueKind!=JsonValueKind.Object ||
               !root.TryGetProperty("version",out var v) ||
               v.ValueKind!=JsonValueKind.String ||
               !root.TryGetProperty("build",out var b) ||
               b.ValueKind!=JsonValueKind.Number ||
               !b.TryGetInt32(out var build)||build<=0)return null;
            var version=v.GetString();
            return version is not null && Ui2VersionPattern.IsMatch(version)
                ?new InstalledBuildInfo(version,build)
                :null;
        }
        catch(JsonException){return null;}
    }

    public static InstalledBuildInfo? ReadFromDirectory(string directory)
    {
        try
        {
            var path=Path.Combine(directory,"build-info.json");
            return File.Exists(path)?Parse(File.ReadAllText(path)):null;
        }
        catch(Exception ex) when(ex is IOException or UnauthorizedAccessException
            or ArgumentException or NotSupportedException)
        {
            return null;
        }
    }
}
